#include <iostream>
#include <string>
#include <algorithm>

int main() {
    std::ios::sync_with_stdio(false);
    std::cin.tie(nullptr);

    std::string line;
    bool firstLine = true;

    while (std::getline(std::cin, line)) {
        if (firstLine) {
            firstLine = false;
            continue;
        }

        int ans = 0;
        int curr = 0;

        for (char ch : line) {
            if (ch == ' ') {
                ans = std::max(ans, curr);
                curr = 0;
            } else if (ch >= 'A' && ch <= 'Z') {
                ++curr;
            }
        }

        ans = std::max(ans, curr);
        std::cout << ans << '\n';
    }

    return 0;
}

